/*
 * Android Broadcast Receiver
 *
 * Usage: frida -U --codeshare leolashkevych/android-broadcast-receiver com.android.systemui
 *
 * 1. Registering a broadcast receiver with a specified intent filter:
 *
 *     registerReceiver(IntentFilter);
 *     registerReceiver('com.example.customAction');
 *
 * 2. Registering a "catch all" broadcast receiver:
 * Android SDK does not allow the registration of a receiver without specifying an intent filter
 * and does not support wildcard filters. This restriction can be circumvented using Java's
 * reflection features to enumerate all applicable events. Then a custom receiver can be
 * registered for each event type. The limitation of this method is the inability to catch
 * non-standard actions/categories/extras. In such cases, use "registerReceiver(IntentFilter);".
 *
 *     registerReceiverForAll();
 *
 * 3. Hook an existing broadcast receiver:
 *
 *   frida -U --codeshare leolashkevych/android-broadcast-receiver -f com.application.receiver
 *   hookReceiver();
 *   hookReceiver(BroadcastReceiverClass);
 *
 * 4. Hook an existing broadcast sender (via the Context.sendBroadcast() method):
 * Note that intents sent with LocalBroadcastManager will not be hooked.
 *
 *   frida -U --codeshare leolashkevych/android-broadcast-receiver -f com.application.sender
 *   hookSender();
 */


function registerReceiver(intentFilter) {
    Java.perform(function() {
        var cxt = getContext();
        if (cxt) {
            const parent = BroadcastReceiver().$new();
            cxt.registerReceiver(ChildBroadcastReceiver().$new(parent), Java.use('android.content.IntentFilter').$new(intentFilter));
        }
    });
}

function registerReceiverForAll() {
    Java.perform(function() {
        var Modifier = Java.use('java.lang.reflect.Modifier');
        var String = Java.use('java.lang.String');
        const parent = BroadcastReceiver().$new();
        var intent = Java.use('android.content.Intent').$new();
        var fields = intent.getClass().getDeclaredFields();
        for (var i = 0; i < fields.length; i++) {
            var field = fields[i];
            var modifiers = field.getModifiers();
            if (Modifier.isPublic(modifiers) && Modifier.isStatic(modifiers) && Modifier.isFinal(modifiers) && field.getType().equals(String.class)) {
                var filter = field.get(intent);
                if (filter) {
                    console.log('Global BroadcastReceiver -> Registered: ' + filter);
                    getContext().registerReceiver(ChildBroadcastReceiver().$new(parent), Java.use('android.content.IntentFilter').$new(filter));
                }
            }
        }
    });
}


function hookReceiver(receiverClassID) {
    if (typeof receiverClassID == 'undefined') {
        receiverClassID = 'android.content.BroadcastReceiver';
    }
    Java.perform(function() {
        var ReceiverClass = Java.use(receiverClassID);
        if (ReceiverClass) {
            ReceiverClass.onReceive.implementation = function(context, intent) {
                printIntent(intent);
                return this.onReceive(context, intent);
            };
            console.log("[+] BroadcastReceiver (" + receiverClassID + ") hook loaded.");
        }
    });
}

function hookSender() {
    Java.perform(function() {
        var Context = Java.use('android.content.Context');
        Context.sendBroadcast.overload('android.content.Intent').implementation = function(intent) {
            printIntent(intent);
            return this.sendBroadcast(intent);
        };
        console.log("[+] Context.sendBroadcast() hook loaded.");
    });
}

function getContext() {
    return Java.use('android.app.ActivityThread').currentApplication().getApplicationContext();
}

function BroadcastReceiver() {
    const ParentBroadcastReceiver = Java.registerClass({
        name: 'ParentBroadcastReceiver',
        superClass: Java.use('android.content.BroadcastReceiver'),
        fields: {
            parent: 'android.content.BroadcastReceiver'
        },
        methods: {
            onReceive: [{
                returnType: 'void',
                argumentTypes: ['android.content.Context', 'android.content.Intent'],
                implementation: function(context, intent) {
                    printIntent(intent);
                }
            }]
        },
    });
    return ParentBroadcastReceiver;
}

function ChildBroadcastReceiver() {
    const ChildBroadcastReceiver = Java.registerClass({
        name: 'ChildBroadcastReceiver',
        superClass: Java.use('android.content.BroadcastReceiver'),
        fields: {
            parent: 'android.content.BroadcastReceiver'
        },
        methods: {
            '<init>': [{
                returnType: 'void',
                argumentTypes: [],
                implementation: function() {}
            }, {
                returnType: 'void',
                argumentTypes: ['android.content.BroadcastReceiver'],
                implementation: function(parent) {
                    this.parent.value = parent;
                }
            }],
            onReceive: [{
                returnType: 'void',
                argumentTypes: ['android.content.Context', 'android.content.Intent'],
                implementation: function(context, intent) {
                    this.parent.value.onReceive(context, intent);
                }
            }]
        },
    });
    return ChildBroadcastReceiver;
}

function printIntent(intent) {
    console.log("\n[*] Intent received. Action: " + intent.getAction());
    var keys = intent.getExtras().keySet();
    var extras = "";
    var iterator = keys.iterator();
    for (var i = 0; i < keys.size(); i++) {
        if (iterator.hasNext()) {
            var key = iterator.next();
            extras += "\n" + key + " = " + intent.getExtras().get(key);
        }
    }
    console.log("[*] Extras:" + extras);
}

Java.perform(function() {
    var Intent = Java.use("android.content.Intent");
    Intent.getData.implementation = function() {
        var action = this.getAction() !== null ? this.getAction().toString() : false;
        if (action) {
            console.log("[*] Intent.getData() was called");
            console.log("[*] Activity: " + this.getComponent().getClassName());
            console.log("[*] Action: " + action);
            var uri = this.getData();
            if (uri !== null) {
                console.log("\n[*] Data");
                uri.getScheme() && console.log("- Scheme:\t" + uri.getScheme() + "://");
                uri.getHost() && console.log("- Host:\t\t/" + uri.getHost());
                uri.getQuery() && console.log("- Params:\t" + uri.getQuery());
                uri.getFragment() && console.log("- Fragment:\t" + uri.getFragment());
                console.log("\n\n");
            } else {
                console.log("[-] No data supplied.");
            }
        }
        return this.getData();
    }
});

Java.perform(function() {
    var System = Java.use('java.lang.System');
    var ActivityThread = Java.use("android.app.ActivityThread");
    var AlertDialogBuilder = Java.use("android.app.AlertDialog$Builder");
    var DialogInterfaceOnClickListener = Java.use('android.content.DialogInterface$OnClickListener');

    Java.use("android.app.Activity").onCreate.overload("android.os.Bundle").implementation = function(savedInstanceState) {
        var currentActivity = this;

        // Get Main Activity
        var application = ActivityThread.currentApplication();
        var launcherIntent = application.getPackageManager().getLaunchIntentForPackage(application.getPackageName());
        var launchActivityInfo = launcherIntent.resolveActivityInfo(application.getPackageManager(), 0);

        // Alert Will Only Execute On Main Package Activity Creation
        if (launchActivityInfo.name.value === this.getComponentName().getClassName()) {
            var alert = AlertDialogBuilder.$new(this);
            alert.setMessage("What you want to do now?");

            alert.setPositiveButton("Dismiss", Java.registerClass({
                name: 'il.co.realgame.OnClickListenerPositive',
                implements: [DialogInterfaceOnClickListener],
                methods: {
                    getName: function() {
                        return 'OnClickListenerPositive';
                    },
                    onClick: function(dialog, which) {
                        // Dismiss
                        dialog.dismiss();
                    }
                }
            }).$new());

            alert.setNegativeButton("Force Close!", Java.registerClass({
                name: 'il.co.realgame.OnClickListenerNegative',
                implements: [DialogInterfaceOnClickListener],
                methods: {
                    getName: function() {
                        return 'OnClickListenerNegative';
                    },
                    onClick: function(dialog, which) {
                        // Close Application
                        currentActivity.finish();
                        System.exit(0);
                    }
                }
            }).$new());

            // Create Alert
            alert.create().show();
        }
        return this.onCreate.overload("android.os.Bundle").call(this, savedInstanceState);
    };
});

Java.perform(function() {
    // Hook startActivityForResult method to inspect the outgoing intent
    var Activity = Java.use("android.app.Activity");

    Activity.startActivityForResult.overload('android.content.Intent', 'int').implementation = function(intent, requestCode) {
        // Call the original method
        this.startActivityForResult(intent, requestCode);

        // Log the outgoing Intent data
        var action = intent.getAction();
        var data = intent.getDataString();

        console.log("startActivityForResult called with:");
        console.log("Request Code: " + requestCode);
        console.log("Action: " + action);
        if (data !== null) {
            console.log("Data: " + data);
        } else {
            console.log("No data associated with the intent.");
        }

        // Optionally, you can log extra fields in the intent
        var extras = intent.getExtras();
        if (extras !== null) {
            var keys = extras.keySet().toArray();
            console.log("Extras: ");
            for (var i = 0; i < keys.length; i++) {
                var key = keys[i];
                console.log(key + ": " + extras.get(key));
            }
        } else {
            console.log("No extras in the intent.");
        }
    };

    // Hook onActivityResult to inspect the returned result
    Activity.onActivityResult.overload('int', 'int', 'android.content.Intent').implementation = function(requestCode, resultCode, data) {
        // Call the original method
        this.onActivityResult(requestCode, resultCode, data);

        console.log("onActivityResult called with:");
        console.log("Request Code: " + requestCode);
        console.log("Result Code: " + resultCode);

        if (data !== null) {
            // Log returned Intent data
            var action = data.getAction();
            var dataString = data.getDataString();

            console.log("Returned Intent Action: " + action);
            if (dataString !== null) {
                console.log("Returned Intent Data: " + dataString);
            } else {
                console.log("No data associated with the returned intent.");
            }

            // Optionally, log returned intent extras
            var extras = data.getExtras();
            if (extras !== null) {
                var keys = extras.keySet().toArray();
                console.log("Returned Extras: ");
                for (var i = 0; i < keys.length; i++) {
                    var key = keys[i];
                    console.log(key + ": " + extras.get(key));
                }
            } else {
                console.log("No extras in the returned intent.");
            }
        } else {
            console.log("No returned intent data.");
        }
    };
});

Java.perform(function() {
    var ActivityThread = Java.use("android.app.ActivityThread");
    var AlertDialogBuilder = Java.use("android.app.AlertDialog$Builder");
    var DialogInterfaceOnClickListener = Java.use('android.content.DialogInterface$OnClickListener');

    const options = [
        "Yeah",
        "Test",
        "Yeah",
        "AAAAA"
    ];


    Java.use("android.app.Activity").onCreate.overload("android.os.Bundle").implementation = function(savedInstanceState) {
        // Get Main Activity
        var application = ActivityThread.currentApplication();
        var launcherIntent = application.getPackageManager().getLaunchIntentForPackage(application.getPackageName());
        var launchActivityInfo = launcherIntent.resolveActivityInfo(application.getPackageManager(), 0);

        // Alert Will Only Execute On Main Package Activity Creation
        if (launchActivityInfo.name.value === this.getComponentName().getClassName()) {
            var alert = AlertDialogBuilder.$new(this);
            alert.setTitle(Java.use("java.lang.StringBuilder").$new("yes title"));
            alert.setSingleChoiceItems(Java.array('java.lang.CharSequence', options), 0, Java.registerClass({
                name: 'dialogue.OnClickListenerSingleChoice',
                implements: [DialogInterfaceOnClickListener],
                methods: {
                    getName: function() {
                        return 'OnClickListenerSingleChoice';
                    },
                    onClick: function(dialog, value) {
                        console.log(options[value])
                    }
                }
            }).$new());

            alert.setNegativeButton(Java.use("java.lang.StringBuilder").$new("test button"), Java.registerClass({
                name: 'dialogue.OnClickListenerNegative',
                implements: [DialogInterfaceOnClickListener],
                methods: {
                    getName: function() {
                        return 'OnClickListenerNegative';
                    },
                    onClick: function(dialog, value) {
                        // Close Application
                        console.log(options[value])
                    }
                }
            }).$new());

            // Create Alert
            alert.create().show();
        }
        return this.onCreate.overload("android.os.Bundle").call(this, savedInstanceState);
    };
});
